<?php $title='Producto'; require __DIR__.'/partials_header.php'; $id=(int)($_GET['id']??0); $p=['id_producto'=>0,'codigo'=>'','nombre'=>'','descripcion'=>'','precio'=>'','stock_actual'=>0,'stock_minimo'=>0,'id_categoria'=>'']; if($id){$s=db()->prepare('SELECT * FROM productos WHERE id_producto=?');$s->execute([$id]);$p=$s->fetch() ?: $p;} $cats=db()->query('SELECT * FROM categorias WHERE estado=1 ORDER BY nombre')->fetchAll(); ?><section class="page-head"><div><p class="eyebrow">Catálogo</p><h1><?=$id?'Editar producto':'Registrar producto'?></h1><p class="muted">Completa la información principal del artículo.</p></div><a class="btn ghost" href="index.php">Volver</a></section><form class="form-card" method="post" action="product_save.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><label>Código<input name="codigo" required maxlength="40" value="<?=e($p['codigo'])?>" placeholder="Ej: CAB-USB-01"></label><label>Nombre<input name="nombre" required maxlength="120" value="<?=e($p['nombre'])?>"></label><label>Categoría<select name="id_categoria" required><option value="">Seleccionar...</option><?php foreach($cats as $c): ?><option value="<?=$c['id_categoria']?>" <?=$p['id_categoria']==$c['id_categoria']?'selected':''?>><?=e($c['nombre'])?></option><?php endforeach; ?></select></label><label>Precio<input type="number" name="precio" min="0" step="0.01" required value="<?=e((string)$p['precio'])?>"></label><label>Stock actual<input type="number" name="stock_actual" min="0" required value="<?=e((string)$p['stock_actual'])?>"></label><label>Stock mínimo<input type="number" name="stock_minimo" min="0" required value="<?=e((string)$p['stock_minimo'])?>"></label><label class="wide">Descripción<textarea name="descripcion" maxlength="500" rows="4"><?=e($p['descripcion'])?></textarea></label></div><div class="form-actions"><a class="btn ghost" href="index.php">Cancelar</a><button class="btn primary" type="submit">Guardar producto</button></div></form><?php require __DIR__.'/partials_footer.php';
